import { PGlite } from "@electric-sql/pglite";
function postgresSql(sql) {
    let index = 0;
    return sql.replace(/\?/g, () => `$${++index}`);
}
export async function createTestPglite() {
    const db = await PGlite.create("memory://");
    return {
        db,
        async exec(sql) {
            await db.exec(sql);
        },
        async query(sql, args = []) {
            return db.query(postgresSql(sql), args.map((value) => (value === undefined ? null : value)));
        },
        prepare(sql) {
            const query = postgresSql(sql);
            return {
                async all(...args) {
                    return (await db.query(query, args)).rows;
                },
                async get(...args) {
                    return (await db.query(query, args)).rows[0];
                },
                async run(...args) {
                    const result = await db.query(query, args);
                    return { changes: result.affectedRows ?? result.rowCount ?? 0 };
                },
            };
        },
        async close() {
            await db.close();
        },
    };
}
